import {ContractError,validDate} from './cloud-contract.mjs';
import {attendanceId,periodRecord} from './attendance-contract.mjs';
import {pagedRows} from './management-model.mjs';
export const calendarModes={default:'按默认周历',work:'调休工作日',rest:'休息日'};
export const monthlyStates={future:'尚未到来','before-start':'入职前','needs-review':'记录待核对',finished:'已签退',working:'工作中','legacy-field':'历史外勤待核对','leave-review':'有批准请假，待核对出勤',rest:'休息日','not-started':'今日未开始','unverified-absence':'无记录，缺勤待核实'};
export function validMonth(v){if(typeof v!=='string'||!/^\d{4}-\d\d$/.test(v)||!validDate(v+'-01')||v<'1900-01'||v>'2199-12')throw new ContractError('请选择有效月份。');return v;}
const nonnegative=v=>{if(!Number.isSafeInteger(v)||v<0)throw new ContractError('月度记录不完整。');return v;};
function day(d){if(!validDate(d.date)||typeof d.workday!=='boolean'||!Object.hasOwn(calendarModes,d.mode)||typeof d.note!=='string')throw new ContractError();nonnegative(d.version);return d;}
export function calendarMonth(v){validMonth(v?.month);if(!Array.isArray(v.days)||v.days.length<28||v.days.length>31||new Set(v.days.map(d=>d.date)).size!==v.days.length)throw new ContractError();v.days.forEach(day);return v;}
export function calendarHistory(v){pagedRows(v);if(v.limit!==50)throw new ContractError();for(const r of v.rows){attendanceId(r.id);if(typeof r.actor_name!=='string'||!Number.isFinite(Date.parse(r.created_at))||!r.after_value)throw new ContractError();}return v;}
export function monthlyResult(v){validMonth(v?.month);if(!validDate(v.today)||!Number.isFinite(Date.parse(v.serverNow))||!Array.isArray(v.roster)||!Array.isArray(v.days))throw new ContractError();for(const m of v.roster){attendanceId(m.id);if(typeof m.name!=='string'||typeof m.active!=='boolean'||typeof m.loginActive!=='boolean'||(m.startDate!==null&&!validDate(m.startDate)))throw new ContractError();}if(v.member===null){if(v.days.length||v.summary!==null)throw new ContractError();return v;}attendanceId(v.member.id);if(!v.roster.some(m=>m.id===v.member.id)||v.days.length<28||v.days.length>31||new Set(v.days.map(d=>d.date)).size!==v.days.length)throw new ContractError();for(const d of v.days){day({...d,...d.calendar});if(!Object.hasOwn(monthlyStates,d.state)||typeof d.employed!=='boolean'||typeof d.complete!=='boolean'||!Array.isArray(d.periods)||!Array.isArray(d.leaves)||!Array.isArray(d.corrections)||!Array.isArray(d.pendingExceptions))throw new ContractError();d.periods.forEach(periodRecord);for(const l of d.leaves){attendanceId(l.id);nonnegative(l.minutes);if(!['approved','pending'].includes(l.status)||typeof l.type!=='string')throw new ContractError();}if(d.metrics){nonnegative(d.metrics.durationMinutes);if(typeof d.metrics.late!=='boolean'||![true,false,null].includes(d.metrics.insufficient))throw new ContractError();}}const fields=['expectedDays','elapsedExpectedDays','normalDays','lateDays','insufficientDays','leaveDays','leaveMinutes','unverifiedAbsenceDays','approvedCorrections','pendingCorrections','restWorkDays','needsReviewDays','pendingExceptions'];if(!v.summary||fields.some(k=>!Object.hasOwn(v.summary,k)))throw new ContractError();fields.forEach(k=>nonnegative(v.summary[k]));return v;}
export function calendarPayload(v){const keys=['requestKey','expectedVersion','mode','note'];if(!v||Object.keys(v).some(k=>!keys.includes(k))||!Object.hasOwn(calendarModes,v.mode)||typeof v.note!=='string'||!v.note.trim()||v.note.trim().length>2000)throw new ContractError('请填写日期安排及原因。');attendanceId(v.requestKey);nonnegative(v.expectedVersion);return {...v,note:v.note.trim()};}
